sys_script_include.script:
var dhMetric = function dhMetric( metric_item ) {
	this.item = metric_item;
};

dhMetric.prototype = {

	TN_CONFIG : 'x_mukl_dh_config',

	// Config type
	CT_METRIC : 'Metric',

	type: 'dhMetric'
};

dhMetric.getEntityMetricMap = function getEntityMetricMap(entity) {

	var TN_CONFIG = dhMetric.prototype.TN_CONFIG;
	var CT_METRIC = dhMetric.prototype.CT_METRIC;

	var map = {
		metrics : {},
		name2id : {}, 
		id2name : {}, 
		system2id : {}
	};

	if ( !entity || !entity.getId() ) { return map; }

	var mr = new GlideRecord(TN_CONFIG);
	mr.addActiveQuery();
	mr.addQuery('entity',entity.getId());
	mr.addQuery('config_type',CT_METRIC);
	mr.query();

	var sid, name, cat, unit;

	while ( mr.next() ) {

		// Collect map and values
		sid  = mr.sys_id + '';
		name = mr.name + '';
		cat  = mr.metric_category + '';
		unit = mr.metric_unit + '';

		map.metrics[sid] = {
			sys_id : sid,
			entity_id : entity.getId(),
			name   : name,
			label  : mr.label + '',
			category : cat,
			unit : unit,
			system_id : mr.system_id + '', 
			value_type: mr.value_type + ''
		};

		// Set up indexes
		map.name2id[name] = sid;
		map.id2name[sid]  = name;
		map.system2id[mr.system_id + ''] = sid;
	}

	return map;
};

//------------------------------------------------
// Public property methods
//------------------------------------------------

dhMetric.prototype.getEntity = function getEntity() {
	return this.item.entity_id;
};

dhMetric.prototype.getEntity = function getEntity() {

	if ( this.entity ) { return this.entity; }

	this.entity = new dhEntity(this.getEntityId());

	return this.entity;
};

dhMetric.prototype.getId = function getId() {
	return this.item.sys_id;
};

dhMetric.prototype.getName = function getName() {
	return this.item.name;
};

dhMetric.prototype.getLabel = function getLabel() {
	return this.item.label;
};

dhMetric.prototype.getUnit = function getUnit() {
	return this.item.unit;
};

dhMetric.prototype.getCategory = function getCategory() {
	return this.item.category;
};

dhMetric.prototype.getTableName = function getTableName() {
	return this.TN_CONFIG;
};

dhMetric.prototype.getItem = function getItem() {
	return this.item;
};

dhMetric.prototype.toString = function toString() {
	return this.type + ' ' + this.getName() + ' [' + this.getTableName() + ':' + this.getId() + ']';
};

//------------------------------------------------
// Internal support methods
//------------------------------------------------
